      {
        "环节": "导入",
        "内容": "通过抛硬币的经典概率引入量子概率，说明波函数归一化就是保证硬币正面概率等于1"
      },
      {
        "环节": "推导",
        "内容": "板书演示归一化条件：∫|ψ(x)|dx = 1，强调绝对值积分"
      },
      {
        "环节": "例题",
        "内容": "计算波函数ψ(x)=Ae^{-x^2}的归一化常数，要求A使得函数在x=0处等于1"
      },
      {
        "环节": "互动",
        "内容": "让学生计算一维无限深势阱中波函数ψ(x)=Asin(nπx/L)的归一化常数，方法是对sin求导找最大值"
      },
      {
        "环节": "拓展",
        "内容": "讨论波函数归一化与经典力学的牛顿第二定律的相似性"
      }
    ]
  }
}

